function demoMain(idx,label){
  var tables=[[["users","id,name,email"],["orders","id,user_id,total"]],[["products","id,sku,price"],["stock","id,product_id,qty"]]];
  var t=tables[idx%tables.length];
  var md=t.map(function(x){return "## "+x[0]+"\ncolumns: "+x[1];}).join("\n");
  return "["+label+"] documented "+t.length+" tables:\n"+md;
}

